/// @file bitfield.hpp
/// @brief Accessors for bit fields of a register-like value, generated by macros.
///
/// A schema is a class with one unsigned integer member named `m_data`; the macros add typed
/// getters and setters for its fields, and `with_*` variants that return a modified copy, so that
/// register values can be built in one expression:
///
/// @code
/// class Lcr {
///   std::uint8_t m_data{};
///
///  public:
///   constexpr explicit Lcr(const std::uint8_t raw = 0) noexcept : m_data(raw) {}
///   BF_RW(std::uint8_t, word_length, 0, 2)
///   BF_BIT_RW(dlab, 7)
/// };
///
/// constexpr auto lcr = Lcr{}.with_word_length(3).without_dlab();
/// @endcode
///
/// Every field is checked at compile time to fit in `m_data`. Setters mask the value to the
/// field width, so an oversized value cannot spill into the neighbouring fields.
#pragma once

#include <concepts>
#include <cstddef>
#include <limits>

/// @brief Read-only field `Name` of `Width` bits at bit `Offset`: `get_Name()`.
#define BF_RO(Type, Name, Offset, Width)                          \
  [[nodiscard]] constexpr Type get_##Name() const noexcept {      \
    using BT = decltype(m_data);                                  \
    static_assert((Offset) + (Width) <= sizeof(BT) * 8,           \
                  "Bitfield [" #Name "] exceeds storage width");  \
    constexpr BT mask = klib::bitfield::make_mask<(Width), BT>(); \
    return static_cast<Type>((m_data >> (Offset)) & mask);        \
  }

#define BF_WO(Type, Name, Offset, Width)                                       \
  constexpr void set_##Name(Type value) noexcept {                             \
    using BT = decltype(m_data);                                               \
    static_assert((Offset) + (Width) <= sizeof(BT) * 8,                        \
                  "Bitfield [" #Name "] exceeds storage width");               \
    constexpr BT mask = klib::bitfield::make_mask<(Width), BT>();              \
    const auto raw_val = static_cast<BT>(value);                               \
    m_data = static_cast<BT>((m_data & static_cast<BT>(~(mask << (Offset)))) | \
                             static_cast<BT>((raw_val & mask) << (Offset)));   \
  }                                                                            \
  [[nodiscard]] constexpr auto with_##Name(Type value) const noexcept {        \
    auto copy = *this;                                                         \
    copy.set_##Name(value);                                                    \
    return copy;                                                               \
  }

/// @brief Read-only flag `Name` at bit `Offset`: `get_Name()`.
#define BF_BIT_RO(Name, Offset)                                                        \
  [[nodiscard]] constexpr bool get_##Name() const noexcept {                           \
    using BT = decltype(m_data);                                                       \
    static_assert((Offset) < sizeof(BT) * 8, "Bit [" #Name "] exceeds storage width"); \
    return ((m_data >> (Offset)) & BT{1}) != 0;                                        \
  }

/// @brief Write-only flag `Name` at bit `Offset`: `set_Name()`, `clear_Name()`, `toggle_Name()`,
///        `with_Name()` and `without_Name()`.
#define BF_BIT_WO(Name, Offset)                                                           \
  constexpr void set_##Name(bool value) noexcept {                                        \
    using BT = decltype(m_data);                                                          \
    static_assert((Offset) < sizeof(BT) * 8, "Bit [" #Name "] exceeds storage width");    \
    m_data = static_cast<BT>((m_data & static_cast<BT>(~(BT{1} << (Offset)))) |           \
                             static_cast<BT>(static_cast<BT>(value) << (Offset)));        \
  }                                                                                       \
  constexpr void set_##Name() noexcept { set_##Name(true); }                              \
  constexpr void clear_##Name() noexcept { set_##Name(false); }                           \
  constexpr void toggle_##Name() noexcept {                                               \
    m_data ^= static_cast<decltype(m_data)>(decltype(m_data){1} << (Offset));             \
  }                                                                                       \
  [[nodiscard]] constexpr auto with_##Name(bool value) const noexcept {                   \
    auto copy = *this;                                                                    \
    copy.set_##Name(value);                                                               \
    return copy;                                                                          \
  }                                                                                       \
  [[nodiscard]] constexpr auto with_##Name() const noexcept { return with_##Name(true); } \
  [[nodiscard]] constexpr auto without_##Name() const noexcept { return with_##Name(false); }

/// @brief Read-write flag: BF_BIT_RO() and BF_BIT_WO() together.
#define BF_BIT_RW(Name, Offset) \
  BF_BIT_RO(Name, Offset)       \
  BF_BIT_WO(Name, Offset)

/// @brief A status bit that the hardware clears when 1 is written to it: `get_Name()`,
///        `mark_clear_Name()` and `with_mark_clear_Name()`.
#define BF_BIT_W1C(Name, Offset)                                                       \
  BF_BIT_RO(Name, Offset)                                                              \
  constexpr void mark_clear_##Name() noexcept {                                        \
    using BT = decltype(m_data);                                                       \
    static_assert((Offset) < sizeof(BT) * 8, "Bit [" #Name "] exceeds storage width"); \
    m_data |= static_cast<BT>(BT{1} << (Offset));                                      \
  }                                                                                    \
  [[nodiscard]] constexpr auto with_mark_clear_##Name() const noexcept {               \
    auto copy = *this;                                                                 \
    copy.mark_clear_##Name();                                                          \
    return copy;                                                                       \
  }

/// @brief Read-write field: BF_RO() and BF_WO() together.
#define BF_RW(Type, Name, Offset, Width) \
  BF_RO(Type, Name, Offset, Width)       \
  BF_WO(Type, Name, Offset, Width)

/// @brief Describes register `Name` at byte offset `Offset` of a device, holding a `Schema`.
///        The access mode decides which of the device's read and write helpers accept it.
#define REG_RW(Name, Offset, Schema)                                             \
  struct Name {                                                                  \
    static constexpr std::size_t offset = Offset;                                \
    using Type = Schema;                                                         \
    static constexpr klib::bitfield::Access access = klib::bitfield::Access::RW; \
  };

#define REG_RO(Name, Offset, Schema)                                             \
  struct Name {                                                                  \
    static constexpr std::size_t offset = Offset;                                \
    using Type = Schema;                                                         \
    static constexpr klib::bitfield::Access access = klib::bitfield::Access::RO; \
  };

#define REG_WO(Name, Offset, Schema)                                             \
  struct Name {                                                                  \
    static constexpr std::size_t offset = Offset;                                \
    using Type = Schema;                                                         \
    static constexpr klib::bitfield::Access access = klib::bitfield::Access::WO; \
  };

namespace klib::bitfield {
/// @brief The `Width` lowest bits of a `T`, all of them if `Width` covers the whole type.
template <std::size_t Width, std::unsigned_integral T>
consteval T make_mask() {
  if constexpr (Width >= sizeof(T) * 8) {
    return std::numeric_limits<T>::max();
  } else {
    return static_cast<T>((T{1} << Width) - 1);
  }
}

enum class Access { RW, RO, WO };

/// @brief A register described with REG_RW() or REG_RO().

template <typename T>
concept ReadableReg = (T::access == Access::RW || T::access == Access::RO);

/// @brief A register described with REG_RW() or REG_WO().
template <typename T>
concept WritableReg = (T::access == Access::RW || T::access == Access::WO);
}  // namespace klib::bitfield
